const input = $input.first().json;
const body = input.body || input;

const errors = [];

const validProviders = ['openai', 'claude', 'gemini', 'mistral'];
const defaultModels = {
  openai: 'gpt-4o',
  claude: 'claude-sonnet-4-20250514',
  gemini: 'gemini-2.5-flash',
  mistral: 'mistral-large-latest'
};

// Validate URLs
if (!body.urls || !Array.isArray(body.urls) || body.urls.length === 0) {
  errors.push('Missing required parameter: urls (array of URLs)');
} else if (body.urls.length > 5) {
  errors.push('Maximum 5 URLs allowed per request');
} else {
  // Validate each URL
  for (const url of body.urls) {
    try {
      new URL(url);
    } catch (e) {
      errors.push(`Invalid URL: ${url}`);
    }
  }
}

const provider = body.provider || 'claude';

if (!validProviders.includes(provider)) {
  errors.push(`Invalid provider: '${provider}'. Valid options: ${validProviders.join(', ')}`);
}

// Check required API keys
if (provider === 'openai' && !body.openai_api_key) {
  errors.push('Missing openai_api_key for OpenAI provider');
}
if (provider === 'claude' && !body.anthropic_api_key) {
  errors.push('Missing anthropic_api_key for Claude provider');
}
if (provider === 'gemini' && !body.google_api_key) {
  errors.push('Missing google_api_key for Gemini provider');
}
if (provider === 'mistral' && !body.mistral_api_key) {
  errors.push('Missing mistral_api_key for Mistral provider');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    urls: body.urls,
    query: body.query || 'Extract all relevant information from this content',
    provider,
    model: body.model || defaultModels[provider],
    openai_api_key: body.openai_api_key,
    anthropic_api_key: body.anthropic_api_key,
    google_api_key: body.google_api_key,
    mistral_api_key: body.mistral_api_key,
    output_schema: body.output_schema || null,
    options: {
      language: body.options?.language || 'fr',
      include_sources: body.options?.include_sources !== false
    },
    callback_url: body.callback_url || null,
    job_id: body.job_id || null,
    conversation_id: body.conversation_id || null,
    user_id: body.user_id || null,
    guild_id: body.guild_id || null,
    channel_id: body.channel_id || null
  }
}];

const data = $input.first().json;

return [{
  json: {
    context: {
      job_id: data.job_id || $runId,
      callback_url: data.callback_url,
      conversation_id: data.conversation_id || '',
      user_id: data.user_id || '',
      guild_id: data.guild_id || '',
      channel_id: data.channel_id || '',
      start_time: Date.now(),
      urls: data.urls,
      query: data.query,
      provider: data.provider,
      model: data.model,
      output_schema: data.output_schema,
      options: data.options,
      openai_api_key: data.openai_api_key,
      anthropic_api_key: data.anthropic_api_key,
      google_api_key: data.google_api_key,
      mistral_api_key: data.mistral_api_key
    }
  }
}];

