const context = $input.first().json.context;
const results = [];

for (const url of context.urls) {
  try {
    const response = await fetch(url, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (compatible; n8n-bot/1.0; +https://n8n.io)',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
        'Accept-Language': context.options.language || 'fr'
      }
    });

    if (!response.ok) {
      results.push({
        url,
        success: false,
        error: `HTTP ${response.status}: ${response.statusText}`,
        content: null
      });
      continue;
    }

    const html = await response.text();

    // Basic HTML to text conversion (remove scripts, styles, and tags)
    let text = html
      .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
      .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
      .replace(/<[^>]+>/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();

    // Limit content length to avoid token limits
    if (text.length > 15000) {
      text = text.substring(0, 15000) + '... [truncated]';
    }

    results.push({
      url,
      success: true,
      error: null,
      content: text
    });

  } catch (e) {
    results.push({
      url,
      success: false,
      error: e.message,
      content: null
    });
  }
}

return [{
  json: {
    context,
    fetched_urls: results,
    successful_count: results.filter(r => r.success).length
  }
}];

