const data = $input.first().json;
const context = data.context;
const fetchedUrls = data.fetched_urls;

// Build content from fetched URLs
const contentParts = fetchedUrls
  .filter(u => u.success)
  .map(u => `=== Content from ${u.url} ===\n${u.content}`)
  .join('\n\n');

if (!contentParts) {
  return [{
    json: {
      context,
      fetched_urls: fetchedUrls,
      llm_response: null,
      error: {
        code: 'NO_CONTENT',
        message: 'Failed to fetch content from any URL'
      }
    }
  }];
}

// Build system prompt
let systemPrompt = `Tu es un expert en extraction de données structurées. Analyse le contenu web fourni et extrait les informations demandées.\n\nRègles:\n1. Extrais uniquement les informations présentes dans le contenu\n2. Si une information n'est pas disponible, utilise null\n3. Respecte strictement le schéma de sortie demandé\n4. Réponds en ${context.options.language === 'fr' ? 'français' : 'anglais'}`;

if (context.output_schema) {
  systemPrompt += `\n\nSchéma de sortie attendu:\n${JSON.stringify(context.output_schema.input_schema || context.output_schema, null, 2)}`;
}

const userPrompt = `${context.query}\n\n${contentParts}`;

// Call appropriate LLM
let apiUrl, headers, body;

switch (context.provider) {
  case 'claude':
    apiUrl = 'https://api.anthropic.com/v1/messages';
    headers = {
      'x-api-key': context.anthropic_api_key,
      'anthropic-version': '2023-06-01',
      'Content-Type': 'application/json'
    };
    body = {
      model: context.model,
      max_tokens: 4096,
      messages: [
        { role: 'user', content: `${systemPrompt}\n\n${userPrompt}` }
      ]
    };
    break;

  case 'openai':
    apiUrl = 'https://api.openai.com/v1/chat/completions';
    headers = {
      'Authorization': `Bearer ${context.openai_api_key}`,
      'Content-Type': 'application/json'
    };
    body = {
      model: context.model,
      max_tokens: 4096,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    };
    if (context.output_schema) {
      body.response_format = { type: 'json_object' };
    }
    break;

  case 'gemini':
    apiUrl = `https://generativelanguage.googleapis.com/v1beta/models/${context.model}:generateContent?key=${context.google_api_key}`;
    headers = { 'Content-Type': 'application/json' };
    body = {
      contents: [{ parts: [{ text: `${systemPrompt}\n\n${userPrompt}` }] }],
      generationConfig: { maxOutputTokens: 4096 }
    };
    break;

  case 'mistral':
    apiUrl = 'https://api.mistral.ai/v1/chat/completions';
    headers = {
      'Authorization': `Bearer ${context.mistral_api_key}`,
      'Content-Type': 'application/json'
    };
    body = {
      model: context.model,
      max_tokens: 4096,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    };
    if (context.output_schema) {
      body.response_format = { type: 'json_object' };
    }
    break;
}

try {
  const response = await fetch(apiUrl, {
    method: 'POST',
    headers,
    body: JSON.stringify(body)
  });

  const result = await response.json();

  if (!response.ok) {
    return [{
      json: {
        context,
        fetched_urls: fetchedUrls,
        llm_response: null,
        error: {
          code: 'LLM_ERROR',
          message: result.error?.message || JSON.stringify(result)
        }
      }
    }];
  }

  return [{
    json: {
      context,
      fetched_urls: fetchedUrls,
      llm_response: result,
      error: null
    }
  }];

} catch (e) {
  return [{
    json: {
      context,
      fetched_urls: fetchedUrls,
      llm_response: null,
      error: {
        code: 'FETCH_ERROR',
        message: e.message
      }
    }
  }];
}

