const data = $input.first().json;
const context = data.context;
const processingTime = Date.now() - context.start_time;

let callback;

if (data.error) {
  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: false,
    result: null,
    metrics: {
      urls_fetched: data.fetched_urls?.length || 0,
      urls_successful: data.fetched_urls?.filter(u => u.success).length || 0,
      processing_time_ms: processingTime
    },
    error: data.error
  };
} else {
  // Extract text from LLM response based on provider
  let extractedText = '';
  const llm = data.llm_response;

  switch (context.provider) {
    case 'claude':
      extractedText = llm.content?.[0]?.text || '';
      break;
    case 'openai':
    case 'mistral':
      extractedText = llm.choices?.[0]?.message?.content || '';
      break;
    case 'gemini':
      extractedText = llm.candidates?.[0]?.content?.parts?.[0]?.text || '';
      break;
  }

  // Try to parse as JSON if output_schema was provided
  let parsedResult = extractedText;
  if (context.output_schema) {
    try {
      const jsonMatch = extractedText.match(/\{[\s\S]*\}/);
      if (jsonMatch) {
        parsedResult = JSON.parse(jsonMatch[0]);
      }
    } catch (e) {
      // Keep as text if parsing fails
    }
  }

  callback = {
    job_id: context.job_id,
    conversation_id: context.conversation_id,
    user_id: context.user_id,
    guild_id: context.guild_id,
    channel_id: context.channel_id,
    success: true,
    result: {
      extracted: parsedResult,
      sources: context.options.include_sources ? data.fetched_urls.map(u => ({
        url: u.url,
        success: u.success,
        error: u.error
      })) : undefined
    },
    metrics: {
      urls_fetched: data.fetched_urls.length,
      urls_successful: data.fetched_urls.filter(u => u.success).length,
      tokens_used: data.llm_response?.usage?.total_tokens || 0,
      processing_time_ms: processingTime
    },
    error: null
  };
}

// RFC-040: Generate HMAC signature
const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';
const payload = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return {
  json: {
    callback,
    callback_url: context.callback_url,
    signature,
    payload
  }
};

